                if cs.ellipsoid:
                    add_ellipsoid(cs.ellipsoid)
                cf_var_grid.grid_north_pole_latitude = (
                    cs.grid_north_pole_latitude
                )
                cf_var_grid.grid_north_pole_longitude = (
